<?php
namespace App\Extensions\ChatbotCustomerTag\System\Services; use App\Extensions\ChatbotCustomerTag\System\Models\ContactIdentity; use Illuminate\Support\Facades\DB;
class ContactIdentityService{public function link(int $customerId,string $channel,string $identifier,array $metadata=[]):ContactIdentity{return ContactIdentity::query()->updateOrCreate(['channel'=>$channel,'normalized_identifier'=>$this->normalize($channel,$identifier)],['chatbot_customer_id'=>$customerId,'identifier'=>$identifier,'metadata'=>$metadata]);}public function duplicates(int $customerId){$ids=ContactIdentity::query()->where('chatbot_customer_id',$customerId)->pluck('normalized_identifier');return ContactIdentity::query()->whereIn('normalized_identifier',$ids)->where('chatbot_customer_id','!=',$customerId)->get();}public function merge(int $targetId,int $sourceId):void{DB::transaction(function()use($targetId,$sourceId){ContactIdentity::where('chatbot_customer_id',$sourceId)->update(['chatbot_customer_id'=>$targetId]);DB::table('ext_chatbot_conversations')->where('chatbot_customer_id',$sourceId)->update(['chatbot_customer_id'=>$targetId]);DB::table('ext_chatbot_customers')->where('id',$sourceId)->delete();});}private function normalize(string $channel,string $v):string{$v=mb_strtolower(trim($v));return in_array($channel,['phone','sms','whatsapp'],true)?preg_replace('/\D+/','',$v):$v;}}
